import sys, heapq


def main():
    data = sys.stdin.read().split()
    n, k = int(data[0]), int(data[1])
    heap = []
    for i in range(n):
        h = int(data[2 + i])
        if len(heap) < k:
            heapq.heappush(heap, h)
        elif h > heap[0]:
            heapq.heapreplace(heap, h)
    print(' '.join(map(str, sorted(heap, reverse=True))))


main()

