def gen(rng):
    def fmt(a, k):
        return f'{len(a)} {k}\n' + ' '.join(map(str, a))

    tests = [
        fmt([1], 1), fmt([10**9], 1), fmt([5, 5, 5], 2), fmt([1, 2, 3, 4, 5], 5),
        fmt([5, 4, 3, 2, 1], 2), fmt([1, 2, 3, 4, 5], 1), fmt([7, 7, 1, 7], 3),
    ]
    for n in (2, 3, 5, 8, 12, 20, 30):
        for _ in range(3):
            a = [rng.randint(1, 10) for _ in range(n)]
            tests.append(fmt(a, rng.randint(1, n)))
    N = 100000
    tests.append(fmt([rng.randint(1, 10**9) for _ in range(N)], N // 2))
    tests.append(fmt([rng.randint(1, 10**9) for _ in range(N)], N))
    tests.append(fmt([rng.randint(1, 5) for _ in range(N)], 40000))
    tests.append(fmt(list(range(N, 0, -1)), 30000))
    return tests

